wsound89_i16 wsoundmuzzledevice89_process_sample(wsoundmuzzledevice89_context*c){wsound89_i32 n,exc,sum,d,w;wsound89_u16 i;wsoundmuzzledevice89_chamber*m;if(!c||!c->active)return 0;n=noise(c);c->low+=(n-c->low)>>((c->type==WSOUNDMUZZLEDEVICE89_SUPPRESSOR)?3:2);exc=(n-c->low);if(c->type==WSOUNDMUZZLEDEVICE89_SUPPRESSOR)exc=(exc>>2)+(c->low>>3);else if(c->type==WSOUNDMUZZLEDEVICE89_BRAKE||c->type==WSOUNDMUZZLEDEVICE89_PORTED)exc+=(n>>2);exc=(exc*c->env)>>15;sum=exc>>2;for(i=0;i<4;i++){m=&c->chamber[i];d=m->delay[m->index];w=exc+((d*m->feedback_q15)>>15);m->delay[m->index]=sat(w);m->index++;if(m->index>=m->length)m->index=0;sum+=(d*m->gain_q15)>>15;}sum=(sum*c->master_q15)>>15;c->env-=(c->env>>((c->type==WSOUNDMUZZLEDEVICE89_SUPPRESSOR)?8:6))+18;if(c->env<30){c->env=0;c->active=0;}return sat(sum);}
